style.css:
@-moz-document domain("web.whatsapp.com") {
/* Background */
  body {
    background: url('https://source.unsplash.com/1920x1080/?nature,green') no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Chat List Background */
  ._3RhW_ {
    background: rgba(0, 50, 0, 0.6) !important;
  }

  /* Chat Window */
  ._1jJ70 {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(10px) !important;
  }

  /* Chat Bubbles */
  .message-in ._22Msk, .message-out ._22Msk {
    background: rgba(0, 80, 0, 0.3) !important;
    border-radius: 15px !important;
    color: #fff !important;
  }

  /* Outgoing Messages */
  .message-out ._22Msk {
    background: rgba(34, 139, 34, 0.5) !important;
  }

  /* Input Field */
  ._13NKt {
    background: rgba(0, 50, 0, 0.8) !important;
    color: #fff !important;
    border-radius: 10px !important;
  }

  /* Remove Unnecessary UI Elements */
  ._2wfYK, ._2nY6U, ._1QUKR, ._3WByx {
    display: none !important;
  }

  /* Header & Icons */
  ._604FD {
    background: rgba(0, 100, 0, 0.8) !important;
  }

  /* Links & Text */
  a, span, div {
    color: #d4edda !important;
  }
}
